css:
.container {
  width: 100%;
  height: 100%;
  background: #0c0a09;
  position: relative;
  overflow: hidden;
  background-image: repeating-radial-gradient(
    circle at 50% 50%,
    #eab308 0px,
    #eab308 10px,
    transparent 11px,
    transparent 20px,
    #10b981 21px,
    #10b981 30px,
    transparent 31px,
    transparent 40px
  );
  background-size: 80px 80px;
  background-position: 0 0;
}
